/**
 * Resolve a loot table into an array of abstract drop descriptors.
 * @param {string} tableId
 * @param {Object} rng - createRng() instance
 * @param {number} depth - current dungeon depth
 * @param {number} [nest=0] - recursion guard
 * @param {Object} [opts] - optional context
 * @param {ReadonlySet<string>} [opts.knownSpells] - spells the player already knows (weight → 0)
 * @returns {Array<{kind:string, params:Object}>}
 */
export function resolveLootTable(tableId, rng, depth, nest = 0, opts) {
  if (nest >= MAX_NESTING) return [];
  const table = LOOT_TABLES[tableId];
  if (!table) return [];

  const results = [];
  const rollCount = rng.int(table.rolls.min, table.rolls.max);

  // Chest tables enforce max 1 weapon rule globally (including nested table calls)
  const isChest = tableId.startsWith("chest:");
  // Share a mutable counter object across nested resolveLootTable calls so the
  // weapon cap is respected even when the weapon comes from a sub-table.
  const weaponRef = isChest ? { count: 0 } : (opts?._weaponRef || null);

  // Some tables, notably chests, promise a meaningful reward before their
  // bonus rolls are resolved. Reuse the same nested-table path so chest-wide
  // constraints (such as one weapon maximum) still apply.
  const guaranteedTables = Array.isArray(table.guaranteedTables) ? table.guaranteedTables : [];
  for (const guaranteedTableId of guaranteedTables) {
    const nestedOpts = weaponRef ? { ...(opts || {}), _weaponRef: weaponRef } : opts;
    results.push(...resolveLootTable(String(guaranteedTableId || ""), rng, depth, nest + 1, nestedOpts));
  }

  for (let r = 0; r < rollCount; r++) {
    const entry = weightedPick(table.entries, rng, opts);
    if (!entry) continue;

    switch (entry.type) {
      case "nothing":
        break;

      case "gold": {
        const base = (entry.count.base || 0) + depth * (entry.count.perDepth || 0);
        const count = Math.max(1, Math.round(base * (0.8 + rng.float(0, 0.4))));
        results.push({ kind: "gold", params: { count } });
        break;
      }

      case "archetype":
        results.push({ kind: "archetype", params: { archetype: entry.archetype } });
        break;

      case "equip": {
        const basePool = Array.isArray(entry.pool) ? entry.pool : [];
        const eligiblePool = basePool.filter((equipId) => {
          const def = getCatalogItem(String(equipId || ""));
          return passesDropRequirement(def, opts);
        });
        const pickPool = eligiblePool.length > 0 ? eligiblePool : basePool;
        const equipId = rng.choice(pickPool);
        if (!equipId) break;

        // Check weapon limit for chests (including when called from a nested table)
        if (weaponRef) {
          const def = getCatalogItem(equipId);
          if (def && def.slot === "weapon") {
            if (weaponRef.count >= 1) break; // Skip this weapon

});

Deno.test("equipped fishing rod use channels and rolls normal-water fishing loot", () => {
  clearAll();
  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE);
  tiles.fill(TILE_FLOOR);
  loadChunk(0, 0, tiles);
  setTile(1, 0, TILE_WATER);

  const world = new World({ seed: 3310 });
  world.rand = () => 0.1;
  const actor = createPlayer(world, { x: 0, y: 0, name: "Angler" });
  installFishingAbilityRuntime(world);
  if (!world.has(actor, Inventory)) world.add(actor, Inventory, { capacity: 20 });
  if (!world.has(actor, Equipment)) world.add(actor, Equipment, {});

  const rod = buildCatalogItem(world, "fishing_rod");
  addToInventory(world, actor, rod);
  world.set(actor, Equipment, { ...world.get(actor, Equipment), weapon: rod });

  const events = [];
  world.on("fishing:caught", (ev) => events.push(ev));

  world.add(actor, UseIntent, { itemId: rod });
  useItemSystem(world);

  assert(world.has(actor, Channeling), "fishing should start a channel");
  for (let i = 0; i < 12; i++) channelingSystem(world);

  assertEquals(world.has(actor, Channeling), false, "fishing channel should complete");
  assertEquals(events.length, 1);
  assertEquals(events[0]?.tableId, "fishing:normal_water");
  if (events[0]?.caughtId) {
    assert(inventoryItems(world, actor).includes(events[0].caughtId), "caught item should enter inventory");
    assert(String(world.get(events[0].caughtId, NamedIdentity)?.identity || "").length > 0);
  }
});

